    },
    {
      "action_name": "auto-Read",
      "description": "读取指定设备参数",
      "description_en": "Read a specified device parameter"
    },
    {
      "action_name": "auto-Set",
      "description": "设置指定设备参数",
      "description_en": "Set a specified device parameter"
    },
    {
      "action_name": "auto-LaserOn",
      "description": "开启激光输出",
      "description_en": "Turn on laser emission"
    },
    {
      "action_name": "auto-LaserOFF",
      "description": "关闭激光输出",
      "description_en": "Turn off laser emission"
    },
    {
      "action_name": "auto-activateLaser",
      "description": "设置激光激活状态",
      "description_en": "Set the laser activation state"
    },
    {
      "action_name": "auto-setMode",
      "description": "设置激光控制模式",
      "description_en": "Set the laser control mode"
    },
    {
      "action_name": "auto-getMode",
      "description": "获取激光控制模式",
      "description_en": "Get the laser control mode"
    },
    {
      "action_name": "auto-setCurrent",
      "description": "设置激光驱动电流",
      "description_en": "Set the laser drive current"
    },
    {
      "action_name": "auto-getCurrent",
      "description": "获取激光驱动电流",
      "description_en": "Get the laser drive current"
    },
    {
      "action_name": "auto-getCurrentSetPoint",
      "description": "获取激光电流设定值",
      "description_en": "Get the laser current setpoint"
    },
    {
      "action_name": "auto-setPower",
      "description": "设置激光输出功率",
      "description_en": "Set the laser output power"
    },
    {
      "action_name": "auto-getPower",
      "description": "获取激光输出功率",
      "description_en": "Get the laser output power"
    },
    {
      "action_name": "auto-getPowerSetPoint",
      "description": "获取激光功率设定值",
      "description_en": "Get the laser power setpoint"
    },
    {
      "action_name": "auto-setAnalogModulation",
      "description": "设置模拟调制状态",
      "description_en": "Set the analog modulation state"
    },
    {
      "action_name": "auto-getAnalogModulation",
      "description": "获取模拟调制状态",
      "description_en": "Get the analog modulation state"
    },
    {
      "action_name": "auto-setDigitalModulation",
      "description": "设置数字调制状态",
      "description_en": "Set the digital modulation state"
    },
    {
      "action_name": "auto-getDigitalModulation",
      "description": "获取数字调制状态",
      "description_en": "Get the digital modulation state"
    },
    {
      "action_name": "auto-getBaseTemperature",
      "description": "获取基座温度",
      "description_en": "Get the base temperature"
    },
    {
      "action_name": "auto-getDiodeTemperature",
      "description": "获取激光二极管温度",
      "description_en": "Get the laser diode temperature"
    },
    {
      "action_name": "auto-getOperatingStatus",
      "description": "获取设备运行状态",
      "description_en": "Get the device operating status"
    },
    {
      "action_name": "auto-getFault",
      "description": "获取设备故障状态",
      "description_en": "Get the device fault status"
    },
    {
      "action_name": "auto-getInterlock",
      "description": "获取联锁状态",
      "description_en": "Get the interlock state"
    },
    {
      "action_name": "auto-getLaserInfo",
      "description": "获取激光器信息",
      "description_en": "Get the laser information"
    }
  ]
}

